def export_to_google_sheets():
    try:
        current_dir = os.path.dirname(os.path.abspath(__file__))
        print(f"Текущая рабочая директория: {current_dir}")

        conn = sqlite3.connect('hr_bot.db')
        c = conn.cursor()
        c.execute('''SELECT id, avito_id, hh_id, name, age, phone, email, status, 
                            test_type, test_code, test_result, personality_type, 
                            recommended_vacancies, interview_slot, source, 
                            created_at, updated_at FROM candidates''')
        candidates = c.fetchall()
        conn.close()

        headers = ['ID', 'Avito ID', 'HH ID', 'Имя', 'Возраст', 'Телефон', 'Email', 
                  'Статус', 'Тип теста', 'Код теста', 'Результат теста', 
                  'Тип личности', 'Рекмендуемые вакансии', 'Слот собеседования', 
                  'Источник', 'Создан', 'Обновлен']

        sh = get_google_sheet()
        if not sh:
            print("Google Sheets connection failed")
            return False

        try:
            worksheet = sh.get_worksheet(0)
        except gspread.exceptions.WorksheetNotFound:
            worksheet = sh.add_worksheet("Кандидаты", rows=100, cols=20)

        worksheet.clear()
        worksheet.append_row(headers)

        for cand in candidates:
            row = []
            for item in cand:
                if item is None:
                    row.append('')
                elif isinstance(item, str):
                    row.append(item)
                else:
                    row.append(str(item))
            worksheet.append_row(row)

        print("Данные успешно экспортированы в Google Sheets!")
        return True

    except Exception as e:
        print(f"Google Sheets export error: {str(e)}")
    return False

