def generate_interview_slots():
    conn = sqlite3.connect('hr_bot.db')
    c = conn.cursor()

    c.execute("DELETE FROM interview_slots WHERE slot_time < ?", (datetime.now().isoformat(),))

    now = datetime.now().replace(minute=0, second=0, microsecond=0)
    slots_count = 0
    for day in range(1, 6):
        for hour in [10, 14, 16]:
            slot_time = now + timedelta(days=day)
            slot_time = slot_time.replace(hour=hour)
            c.execute(
                "INSERT OR IGNORE INTO interview_slots (slot_time, is_booked) VALUES (?, 0)",
                (slot_time.isoformat(),)
            )
            slots_count += 1
    conn.commit()
    conn.close()
    return slots_count

def get_available_slots():
    conn = sqlite3.connect('hr_bot.db')
    c = conn.cursor()
    c.execute("SELECT id, slot_time FROM interview_slots WHERE is_booked = 0 AND slot_time > datetime('now')")
    slots = c.fetchall()
    conn.close()
    return slots

