        if candidate['source'] == 'avito':
            token = get_avito_token()
            return token and send_avito_message(token, candidate['dialog_id'], text)
        elif candidate['source'] == 'hh':
            token = get_stored_hh_token()
            return token and send_hh_message(token, candidate['dialog_id'], text)
    except Exception as e:
        print(f"Send message error: {str(e)}")
